function step(key, order, title, kind, status, overrides = {}) {
  const operationId = String(overrides.operationId || 'op-email-happy');
  const { operationId: _operationId, ...stepOverrides } = overrides;
  return {
    id: `${operationId}:email_ops_v1:${key}`,
    order,
    title,
    kind,
    status,
    dependsOn: [],
    startedAt: BASE_TIME,
    completedAt: status === 'pending' ? null : '2026-04-24T18:02:00.000Z',
    updatedAt: '2026-04-24T18:02:00.000Z',
    detail: null,
    evidenceRefs: [],
    outputRefs: [],
    approvalRefs: [],
    repairOfStepId: null,
    childRunRefs: [],
    ...stepOverrides,
  };
}

function output(id, kind, title, status, overrides = {}) {
  return {
    id,
    kind,
    title,
    status,
    rendererChatOutputKey: null,
    externalRef: null,
    ...overrides,
  };
}

function approval(id, title, status, overrides = {}) {
  return {
    id,
    title,
    status,
    reviewSessionId: null,
    outputRef: null,
    ...overrides,
  };
}

